.skill-container { font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #e0e0e0; width: 320px; border: 1px solid rgba(0, 180, 255, 0.3); border-radius: 4px; box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5); overflow: hidden; }
.skill-header { display: flex; background: rgba(0, 120, 255, 0.2); font-weight: bold; font-size: 10px; text-transform: uppercase; padding: 6px 8px; cursor: pointer; border-bottom: 1px solid rgba(255, 255, 255, 0.1); align-items: center; }
