.col-name { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; display: flex; align-items: center; justify-content: space-between; }
.col-val { width: 65px; text-align: right; flex-shrink: 0; }
.col-cnt { width: 35px; text-align: right; flex-shrink: 0; }
.col-pct { width: 45px; text-align: right; flex-shrink: 0; }
.col-reset { font-size: 14px; cursor: pointer; margin-left: 5px; }
.col-reset:hover { color: #ff4444; }
.skill-list { max-height: 400px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: rgba(0, 180, 255, 0.5) rgba(0, 0, 0, 0.2); }
.skill-row { display: flex; padding: 4px 8px; font-size: 12px; border-bottom: 1px solid rgba(255, 255, 255, 0.03); align-items: center; }
.skill-row .col-val { font-family: 'Courier New', monospace; color: #00ffaa; }
